#include <stdio.h>
#include <ctype.h>

int main(void)
{
    long lines = 0;   // LINES
    long words = 0;   // WORDS
    long chars = 0;   // CHARS

    int c;
    int in_word = 0;  // non-zero while inside a word

    while ((c = getchar()) != EOF) {
        chars++;
        if (c == '\n')
            lines++;
        if (isspace((unsigned char)c)) {
            if (in_word) {
                words++;
                in_word = 0;
            }
        } else {
            in_word = 1;
        }
    }
    // Do not count a trailing word without following whitespace, matching original FSM.
    printf("LINES=%ld WORDS=%ld CHARS=%ld\n", lines, words, chars);
    return 0;
}
